    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math

def gcd(a,b):
    while b:
        a,b=b,a%b
    return a

tries = 0
while True:
    tries += 1
    if tries > 2000:
        # Fallback deterministic safe parameters
        lambda_num, lambda_den = 5, 4
        c_num, c_den = 9, 5
        break
    # Pick lambda in (0.5, 2.5), avoid 1
    ln = rng.randint(2, 20)
    ld = rng.randint(2, 20)
    g = gcd(ln, ld)
    ln //= g; ld //= g
    lam = ln/ld
    if not (0.5 < lam < 2.5):
        continue
    if ln == ld:
        continue
    # Pick c in (1/50, 50), avoid 1
    cn = rng.randint(2, 400)
    cd = rng.randint(2, 400)
    g2 = gcd(cn, cd)
    cn //= g2; cd //= g2
    c = cn/cd
    if not (1/50 < c < 50):
        continue
    if cn == cd:
        continue
    # Compute bound and ensure it's well away from integers for numerical stability
    B = 10.0/(lam * (c ** 0.25))
    if not (math.isfinite(B) and B > 1.5 and B < 35):
        continue
    n_star = math.floor(B + 1e-12)
    if n_star < 2 or n_star > 25:
        continue
    # keep away from integer boundaries by a margin
    if abs(B - round(B)) < 0.05:
        continue
    # All good
    lambda_num, lambda_den = ln, ld
    c_num, c_den = cn, cd
    break

return {
    'lambda_num': lambda_num,
    'lambda_den': lambda_den,
    'c_num': c_num,
    'c_den': c_den
}

